E", "e",$0100,$0100}	// key equivalents	}};};resource rPString (EjectBtn) {	"Eject"};resource rControlTemplate (MainList) {	MainList,		// ID	{  4, 10, 86,284},	// rect	listControl {{		$0000,		// flag		fCtlProcNotPtr+fCtlIsMultiPart+refIsPointer,	// moreFlags		$00000000, 	// refCon		$0000,		// listSize		$0008,		// listView		$0000,		// listType		$0000,		// listStart		$000A,		// listMemHeight		$0008,		// listMemSize		$00000000	// listRef	}};};resource rControlTemplate (VersionStr) {	VersionStr,		// ID	{107,270,116,315},	// rect	statTextControl {{		$0000,		// flag		fCtlProcNotPtr+refIsPointer,	// moreFlags		$00000000, 	// refCon		0,	// textRef		0,	// textSize		$0000		// just	}};};resource rPString (SFPromptStr) {	"Select an Image file"};resource rAlertString (AboutBox) {	"35~Mount Image GS"	"\$0D"	"by Steve Stephenson~^Cool"	"\$00"};resource rVersion (1) {	{ 1, 0, 0, development, 1},	verUS,	"Mount Image GS",	"Copyright 1993 Apple Computer, Inc."};// need rComment (1)// need rComment (2)// need rIcon// need rBundle